import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"37、【家人】 离下巽上","description":"周易阐真 - 37、【家人】 离下巽上","frontmatter":{"title":"37、【家人】 离下巽上","description":"周易阐真 - 37、【家人】 离下巽上"},"headers":[],"relativePath":"zh/classics/chanzhen/038.md","filePath":"zh/classics/chanzhen/038.md"}'),s={name:"zh/classics/chanzhen/038.md"};function n(c,a,i,o,h,l){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：家人，女正位乎内，男正位乎外。男女正，天地之大义也。家人有严君焉，父母之谓也。父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正。正家而天下定矣。</p></blockquote><h1 id="_37、【家人】-离下巽上" tabindex="-1">37、【家人】 离下巽上 <a class="header-anchor" href="#_37、【家人】-离下巽上" aria-label="Permalink to “37、【家人】 离下巽上”">​</a></h1><p>初九：闲有家，悔亡。</p><p>六二：无攸遂，在中馈，贞吉。</p><p>九三：家人嗃嗃，悔厉吉。妇子嘻嘻，终吝。</p><p>六四：富家，大吉。</p><p>九五：王假有家，勿恤，吉。</p><p>上九：有孚威如，终吉。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：风自火出，家人。君子以言有物而行有恒。</p><p>家人者，一家之人也。上巽风，下离火，是火在内，风在外，风自火出，火燃而风自生，风火一家，家人之象也。</p><p>君子有见于此，知风火一处，风生必本于火，火燃而风自生；人我同居，成物必本于己，己正而人自化。以是言不空言，言必有物；行不妄行，行必有恒。谨言慎行，则同居者皆亦言物行恒，而与我为一家之人矣。家人不仅是同家之人，凡与我同居同事者皆是。物，如事也；恒，有终也。言有物者，因事而言；有指有证，言必合理。行有恒者，有终之行；真履实践，行必有成。以物而言，以恒而行，言行无亏，内不失己，外不伤人，则同居同事者，俱默相感化，亦如火燃而风自生矣。夫言者，心之声；行者，身之律。修道者，有物而言，有恒而行，则心正身修，性命有寓，方且上下与天地同流，而以天地为一家，岂第家人而矣哉！</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>馈，音匮。嗃，音郝。嘻，音希。</p><p>家人者，家中有人，治内之道。卦德上巽入，下离明，明则可以巽行其道，巽则能以渐通其明，巽明相需，如以风吹火，火随风生，有治家之道，故谓家人。此炼己持心、回光返照之卦，承上晋卦而来。晋者，明由顺生，进火用明之功。进火用明，须先明内，明内者炼己也。炼己者，炼我家之阴耳。我家之阴为何阴?人心是也。人身精、神、魂、魄、意，皆属阴，听命于人心，人心静而五者皆静，人心动而五者皆动，炼己即炼此人心耳。炼去人心，道心自现，道心现而心明，则精、神、魂、魄、意，皆化而为护法神矣。</p><p>人之身，如家也；人之精、神、魂、魄、意，如一家之人也。炼人心而生道心，精、神、魂、魄、意，各安其位，各伺其事，喜、怒、哀、乐，皆和而中节，如一家治也。取象利女贞，女以守贞为贵，炼己如女之守贞不字，则我家之真阴现象。真阴现象，则心虚灵不昧，外物不得而入，可以循序渐进，以求他家之阳，无有不利者。卦体二虚于下，五实于上。虚心即能以实腹，利女贞，正所以致虚守静，以为成家立业计耳。故修道者，戒慎恐惧，于不睹不闻之内，不使有一毫阴气潜藏于方寸之中也。</p><p>初九，在家人之初，刚于炼己，如闲有家也。有己即能防闲克制，方寸之中，空空洞洞，内念不生，外不入，本有悔而悔可亡。此炼已于有己之初者也。</p><p>六二，柔而中正，返观内照，心清意静，不专遂于外，而谨慎于内，以静制动，以一御纷，外物不纳，客气难入，如妇人在中馈而居贞，未有不得吉者。此炼己而用柔道者也。</p><p>九三，炼己功勤，杂念不生，如家人嗃嗃，悔厉惊惧，不敢为恶，自然得吉。否则有念不去，姑息养奸，恣情纵欲，如妇子嘻嘻，略无家法，焉能到得无己之时?如此修道，终不成道，取吝而已。此炼己当用刚道者也。</p><p>六四，以柔求刚，借刚济柔，不即不离，渐次导引。虚心即能实腹，富有日新，方且积法财、聚天宝，其吉之大，不仅无己而已。此炼己柔而用刚者也。</p><p>九五，阳刚得中，心正而身修，如王者假家施治，而天下自平，其吉出于自然，非有勉强，何忧恤之有?此炼己而刚柔如一者也。</p><p>上九，刚而居于巽体之上，可信其炼己有威如矣。炼己威如，严之于初，自能吉之于终。此炼己而有始有终者也。</p><p>子书云：“炼己不熟，还丹不结。”还丹头一步功夫，先要炼己，炼己炼到无己时，虚室生白，先天之气，自虚无中来，凝结而成黍米之珠，其光通天彻地，一切魍魉邪魔，焉得而近之？炼己之功岂小焉哉!</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
